Update SessionCompaction.renegotiate() to call the new impulse-only renegotiateContext().

## Task

In `src/session/compaction.ts`, update the `renegotiate()` function:

### Remove Old Code

Remove:
- Message loading and token calculation (lines ~113-139)
- Message passing to renegotiateContext
- Message compaction logic (lines ~169-181)

### New Implementation

```typescript
export async function renegotiate(input: {
  sessionID: string
  providerID: string
  modelID: string
  signal?: AbortSignal
}) {
  if (!input.signal) SessionLock.assertUnlocked(input.sessionID)
  await using lock = input.signal === undefined ? SessionLock.acquire({ sessionID: input.sessionID }) : undefined
  const signal = input.signal ?? lock!.signal

  await Session.update(input.sessionID, (draft) => {
    draft.time.compacting = Date.now()
  })
  await using _ = defer(async () => {
    await Session.update(input.sessionID, (draft) => {
      draft.time.compacting = undefined
    })
  })

  log.info("renegotiating context", {
    sessionID: input.sessionID,
  })

  // Use memory agent to decide what to keep/remove
  // Memory agent loads impulses internally
  const { SessionMemoryAgent } = await import("./memory-agent")
  const decision = await SessionMemoryAgent.renegotiateContext({
    sessionID: input.sessionID,
    model: {
      providerID: input.providerID,
      modelID: input.modelID,
    },
  })

  log.info("renegotiation decision", {
    sessionID: input.sessionID,
    impulsesToUnload: decision.impulsesToUnload.length,
    impulsesToDelete: decision.impulsesToDelete.length,
    estimatedSaved: decision.estimatedTokensSaved,
    reasoning: decision.reasoning,
  })

  // Execute the decision
  const { SessionMemory } = await import("./session-memory")

  // Unload impulses (keep pointer, free content)
  for (const impulseID of decision.impulsesToUnload) {
    await SessionMemory.updateImpulse(input.sessionID, impulseID, {
      loaded: false,
      content: undefined,
    })
    log.debug("unloaded impulse", { impulseID })
  }

  // Remove impulses permanently
  for (const impulseID of decision.impulsesToDelete) {
    await SessionMemory.removeImpulse(input.sessionID, impulseID)
    log.debug("removed impulse", { impulseID })
  }

  // Create summary note if context was renegotiated
  if (decision.impulsesToUnload.length > 0 || decision.impulsesToDelete.length > 0) {
    const summaryText = `[Context renegotiated: ${decision.impulsesToUnload.length} impulses unloaded, ${decision.impulsesToDelete.length} impulses removed]\n\nReasoning: ${decision.reasoning}`

    const resumeMsgID = Identifier.ascending("message")
    await Session.updateMessage({
      id: resumeMsgID,
      role: "user",
      sessionID: input.sessionID,
      time: {
        created: Date.now(),
      },
    })

    await Session.updatePart({
      type: "text",
      sessionID: input.sessionID,
      messageID: resumeMsgID,
      id: Identifier.ascending("part"),
      text: summaryText,
      time: {
        start: Date.now(),
        end: Date.now(),
      },
      synthetic: true,
    })
  }

  Bus.publish(Event.Compacted, {
    sessionID: input.sessionID,
  })

  return {
    decision,
    tokensFreed: decision.estimatedTokensSaved,
  }
}
```

## Acceptance Criteria

- [ ] Removes message loading logic
- [ ] Calls renegotiateContext with simplified interface
- [ ] Executes impulse unload/delete decisions
- [ ] Creates summary message for user
- [ ] Publishes compaction event
- [ ] No compilation errors
- [ ] Maintains backward compatibility

Update getMessages() in prompt.ts to reconstruct messages from impulse loading state.

## Context

After renegotiation, some turn impulses will be unloaded. getMessages() should only return messages whose turn impulses are loaded.

## Task

In `src/session/prompt.ts`, update the `getMessages()` function:

```typescript
async function getMessages(input: {
  sessionID: string
  model: ModelsDev.Model
  providerID: string
  signal: AbortSignal
}) {
  // Get all messages
  let msgs = await MessageV2.filterCompacted(MessageV2.stream(input.sessionID))

  // Check if we need compaction
  const lastAssistant = msgs.findLast((msg) => msg.info.role === "assistant")
  if (
    lastAssistant?.info.role === "assistant" &&
    SessionCompaction.isOverflow({
      tokens: lastAssistant.info.tokens,
      model: input.model,
    })
  ) {
    // Check compaction strategy from config
    const cfg = await Config.get()
    const strategy = cfg.sessionMemory?.compaction?.strategy ?? "renegotiate"

    if (strategy === "renegotiate" || strategy === "auto") {
      try {
        // Use intelligent renegotiation: memory agent decides what to keep/remove
        await SessionCompaction.renegotiate({
          sessionID: input.sessionID,
          providerID: input.providerID,
          modelID: input.model.id,
          signal: input.signal,
        })

        // After renegotiation, filter messages by loaded impulses
        const { SessionMemory } = await import("./session-memory")
        const impulses = await SessionMemory.listImpulses(input.sessionID)
        const turnImpulses = impulses.filter(i => i.type === "messageHistory")

        // Get loaded turn impulses
        const loadedTurns = new Set(
          turnImpulses
            .filter(i => i.loaded)
            .flatMap(i => {
              if (i.pointer.type === "messageHistory") {
                return i.pointer.messageIDs
              }
              return []
            })
        )

        // Filter messages to only include those in loaded turns
        msgs = msgs.filter(msg => loadedTurns.has(msg.info.id))

        log.info("filtered messages by loaded impulses", {
          totalMessages: (await MessageV2.stream(input.sessionID)).length,
          loadedMessages: msgs.length,
          loadedTurns: loadedTurns.size,
        })

      } catch (error) {
        log.warn("renegotiation failed, falling back to summarization", {
          error: error instanceof Error ? error.message : String(error),
        })
        if (strategy === "auto") {
          // Fallback to summarization
          const summaryMsg = await SessionCompaction.run({
            sessionID: input.sessionID,
            providerID: input.providerID,
            modelID: input.model.id,
            signal: input.signal,
          })
          const resumeMsgID = Identifier.ascending("message")
          const resumeMsg = {
            info: await Session.updateMessage({
              id: resumeMsgID,
              role: "user",
              sessionID: input.sessionID,
              time: {
                created: Date.now(),
              },
            }),
            parts: [
              await Session.updatePart({
                type: "text",
                sessionID: input.sessionID,
                messageID: resumeMsgID,
                id: Identifier.ascending("part"),
                text: "Use the above summary generated from your last session to resume from where you left off.",
                time: {
                  start: Date.now(),
                  end: Date.now(),
                },
                synthetic: true,
              }),
            ],
          }
          msgs = [summaryMsg, resumeMsg]
        } else {
          throw error
        }
      }
    } else {
      // Use traditional summarization
      const summaryMsg = await SessionCompaction.run({
        sessionID: input.sessionID,
        providerID: input.providerID,
        modelID: input.model.id,
        signal: input.signal,
      })
      const resumeMsgID = Identifier.ascending("message")
      const resumeMsg = {
        info: await Session.updateMessage({
          id: resumeMsgID,
          role: "user",
          sessionID: input.sessionID,
          time: {
            created: Date.now(),
          },
        }),
        parts: [
          await Session.updatePart({
            type: "text",
            sessionID: input.sessionID,
            messageID: resumeMsgID,
            id: Identifier.ascending("part"),
            text: "Use the above summary generated from your last session to resume from where you left off.",
            time: {
              start: Date.now(),
              end: Date.now(),
            },
            synthetic: true,
          }),
        ],
      }
      msgs = [summaryMsg, resumeMsg]
    }
  }
  return msgs
}
```

## Acceptance Criteria

- [ ] After renegotiation, filters messages by loaded impulses
- [ ] Only includes messages whose turn impulse is loaded
- [ ] Logs message filtering stats
- [ ] Maintains fallback to summarization
- [ ] No compilation errors

